return-response.set-body:
{
                        "status": 403,
                        "error": "Forbidden",
                        "message": "Access Denied. Customers are not authorized to view the customer directory."
                    }

when.set-body:
@{
                    var jwt = context.Request.Headers.GetValueOrDefault("Authorization","").Split(' ').Last().AsJwt();
                    if (jwt != null) 
                    {
                        var roles = jwt.Claims.GetValueOrDefault("roles", "");
                        var customerId = jwt.Claims.GetValueOrDefault("customerId", "");
                        var email = jwt.Claims.GetValueOrDefault("email", "");
                        var userId = jwt.Claims.GetValueOrDefault("userId", "");

                        if (roles.Contains("CUSTOMER"))
                        {
                            var profileRaw = context.Variables.GetValueOrDefault("resolvedProfile", "");
                            if (!string.IsNullOrEmpty(profileRaw))
                            {
                                try
                                {
                                    var pJson = JObject.Parse(profileRaw);
                                    if (string.IsNullOrEmpty(customerId) && pJson["id"] != null)
                                    {
                                        customerId = pJson["id"].ToString();
                                    }
                                    if (string.IsNullOrEmpty(email) && pJson["email"] != null)
                                    {
                                        email = pJson["email"].ToString();
                                    }
                                }
                                catch (Exception) {}
                            }
                        }

                        try 
                        {
                            var bodyString = context.Request.Body.As(preserveContent: true);
                            if (!string.IsNullOrWhiteSpace(bodyString)) 
                            {
                                JObject body = JObject.Parse(bodyString);

                                if (roles.Contains("CUSTOMER")) 
                                {
                                    if (!string.IsNullOrEmpty(customerId)) {
                                        body["customerId"] = customerId;
                                    }
                                    if (!string.IsNullOrEmpty(email)) {
                                        body["customerEmail"] = email;
                                    }
                                }
                                else if (roles.Contains("MANAGER") || roles.Contains("EMPLOYEE"))
                                {
                                    if (!string.IsNullOrEmpty(userId)) {
                                        body["managerId"] = userId;
                                    }
                                }

                                return body.ToString();
                            }
                        }
                        catch (Exception)
                        {
                            // If parsing fails, fall through to return original body
                        }
                    }
                    return context.Request.Body.As(preserveContent: true);
                }
